#!/usr/bin/env bash\n# test_labeler.sh – verifies that the action correctly maps emojis to labels\n\nset -e\n\n# Create a temporary directory for the mock event\nTMPDIR=$(mktemp -d)\nEVENT_FILE="$TMPDIR/event.json"\n\n# Mock payload with a PR title containing several emojis\ncat > "$EVENT_FILE" <<'EOF'\n{\n  "pull_request": {\n    "title": "Fix typo 🐛 and add docs 📝 ✨"\n  }\n}\nEOF\n\n# Export the required env var\nexport GITHUB_EVENT_PATH="$EVENT_FILE"\n\n# Run the action's main script\nOUTPUT=$(node src/index.js)\n\n# Expected labels: bug, documentation, sparkles\nEXPECTED="Would add labels: bug, documentation, sparkles"\n\nif [[ "$OUTPUT" == "$EXPECTED" ]]; then\n  echo "✅ test passed"\n  exit 0\nelse\n  echo "❌ test failed"\n  echo "Expected: $EXPECTED"\n  echo "Got:      $OUTPUT"\n  exit 1\nfi\n
